/* ── СТРАЖИ: по два-три на сектор; ключ-карта — у стража в секторах с card: "boss",
   спрятана на этаже — в секторах с card: "hidden" ── */
D({ bosses: {
  v8_b_receiver: { base: "v8_intaker", n: "Старший приёмщик", g: "m",
    desc: "Приёмщик, принявший за века больше материала, чем помнит журнал. Захваты у него в рост человека: держат так, что ноги не слушаются. Зовёт подборщиков — прибрать то, что останется. Ионы и ЭМИ режут гидравлику захватов; шлюзовая ключ-карта висит у него на захвате, как номерной жетон.",
    mult: 5, beh: ["chase", "slow", "summon", "dooropen"], snd: "guardbot", sndRate: 0.8, minion: "v8_picker" },
  v8_b_counter: { base: "v8_leader", n: "Учётчик материала", g: "m",
    desc: "Ведущий приёмки: каждому, кого слышит, выкрикивает номер и вносит в журнал. Командует приёмщиками, и рядом с ним они хватают злее. Сам держится позади; ЭМИ глушит его голосовой узел. Ключ-карта — в планшете у него на груди, планшет щёлкает при каждой записи.",
    mult: 5, beh: ["ranged", "commander", "summon", "dooropen"], rng: 5, snd: "android", sndRate: 0.75, minion: "v8_intaker" },
  v8_b_heavy: { base: "v8_overgrown", n: "Тяжеловес", g: "m",
    desc: "Перегруз, переживший все стенды корпуса: его давили, крутили и оглушали, пока он не перестал замечать боль. Бьёт с разгона так, что гудит пол, и затягивает раны на ходу. Пули в нём вязнут; жар и плазма берут лучше.",
    mult: 6, beh: ["chase", "charge", "regen"], snd: "chimera", sndRate: 0.65 },
  v8_b_standmaster: { base: "v8_rigger", n: "Хозяин стендов", g: "m",
    desc: "Сборщик, что ставил стенды для всего корпуса, — и в бою ставит их прямо вокруг вас: лёгкие турели вырастают одна за другой, пока он цел. Зовёт наладчиков. Слушайте гайковёрт: пока он стучит, турели прибывают.",
    mult: 5, beh: ["ranged", "builder", "summon"], rng: 4, snd: "sapper", sndRate: 0.85, minion: "v8_mender" },
  v8_b_firststep: { base: "v8_walker", n: "Шагоход «Первый шаг»", g: "m",
    desc: "Самый первый шагоход Зинаиды Глотовой: огромный, медленный, на шести опорах. Каждый его шаг — удар, от которого сыплется пыль с потолка; разогнавшись, он сметает всё на соседних клетках. Зовёт разведчиков. Ключ-карта — в кабине, на шнурке: Глотова вешала туда ключи.",
    mult: 5, beh: ["chase", "charge", "splash", "summon"], rng: 2, snd: "titan", sndRate: 0.7, minion: "v8_strider" },
  v8_b_heron: { base: "v8_strider", n: "Шагоход «Цапля»", g: "f",
    desc: "Двуногая машина-разведчик, любимица Шагодрома: слышит шаги через весь этаж и приходит раньше, чем вы успеете спрятаться. Стреляет на бегу и зовёт дронов-иглачей. Колени у неё открыты — ионом в сустав, и она садится. Ключ-карта у неё под брюхом, в кассете самописца.",
    mult: 6, beh: ["ranged", "tracker", "summon"], rng: 5, snd: "spiderbot", sndRate: 1.05, minion: "v8_dart" },
  v8_b_zero: { base: "v8_proto", n: "Изделие «Ноль»", g: "n",
    desc: "Первый прототип с обучаемым мозгом. Его испытывали дольше всех и научили всему: он привыкает к любому оружию и сам затягивает повреждения. Меняйте оружие каждые два-три удара и не давайте ему передышки.",
    mult: 6, beh: ["chase", "adapt", "regen"], snd: "android", sndRate: 1.3 },
  v8_b_cordonchief: { base: "v8_cordon", n: "Начальник оцепления", g: "m",
    desc: "Машина, что держала оцепление вокруг огневых труб. Её поле прикрывает всех машин рядом, а минёры по её зову засевают проходы. Поле проседает на тон, когда перезаряжается, — тогда и бейте.",
    mult: 5, beh: ["ranged", "shieldally", "summon"], rng: 5, snd: "shieldbot", sndRate: 0.75, minion: "v8_sapper" },
  v8_b_remaker: { base: "v8_modder", n: "Главный переделчик", g: "m",
    desc: "Автомат самого первого шлюза: двенадцать рук, двенадцать игл, и все стрекочут вразнобой. Укол травит и сковывает, а по его зову из шлюза выходят расползни. Держитесь на расстоянии и бейте шоком. Ключ-карта зажата в одной из рук — в той, что не стрекочет.",
    mult: 6, beh: ["chase", "poison", "slow", "summon"], snd: "spiderbot", sndRate: 0.7, minion: "v8_reject" },
  v8_b_first: { base: "v8_remade", n: "Первая поправленная", g: "f",
    desc: "Её звали Пелагея Деева. Её переделали первой из наказанных — за лишний паёк для сына. Разум остался, имя — нет. Она стоит у шлюза и не пускает туда никого, будто ещё можно кого-то не пустить, и зовёт тех, кого поправили после неё. Ключ-карта — в её браслете с пустой капсулой.",
    mult: 5, beh: ["chase", "dooropen", "summon", "howl"], snd: "labmut", sndRate: 0.95, minion: "v8_remade" },
  v8_b_mistress: { base: "v8_queen", n: "Хозяйка коконника", g: "f",
    desc: "Доброволица Ульяна Мокеева пошла в шлюз сама — научиться жить внизу — и вышла матерью коконов. Она держит гнездо, поёт ему сквозь шёлк и рожает вылупков, лечит своих и бьёт по нервам. Пока она гудит, гнездо спит. Сначала уберите сиделок; жар её шёлк не любит.",
    mult: 5, beh: ["stationary", "summon", "healer", "psi"], snd: "weaver", sndRate: 0.6, minion: "v8_hatchling" },
  v8_b_spinmaster: { base: "v8_spinner", n: "Старший коконопряд", g: "m",
    desc: "Старейший прядильщик коконника: его нить толще каната и звенит, как струна. Плюётся шёлком, опутывает проходы растяжками и зовёт вылупков. Огонь и жар рвут его пряжу лучше всего.",
    mult: 6, beh: ["ranged", "web", "trapper", "summon"], rng: 4, snd: "weaver", sndRate: 0.9, minion: "v8_hatchling" },
  v8_b_bury: { base: "v8_cullhound", n: "Бурый", g: "m",
    desc: "Вожак браковой своры, крупный, с седой холкой. Нижние говорят, порода ведёт род от пса первых — того, что пошёл сам; этот идёт сам по любому следу через весь этаж. Перед броском хрипло лает и скликает свору. Ключ-карту носит на ошейнике — там, где у бурых из вивария была кличка.",
    mult: 6, beh: ["chase", "tracker", "howl", "summon"], snd: "chimera", sndRate: 1.0, minion: "v8_cullhound" },
  v8_b_heap: { base: "v8_reject", n: "Сросток", g: "m",
    desc: "Десятки расползней, сросшихся в одну тушу. Не видит, идёт на шум, хватает всем сразу, а раненый распадается на куски, и каждый ползёт сам. Жар и плазма берут его лучше пуль. Ключ-карта — в чьём-то браслете внутри: её слышно, когда он ворочается.",
    mult: 6, beh: ["chase", "split", "summon", "deaf"], snd: "labmut", sndRate: 0.65, minion: "v8_reject" },
  v8_b_shuffler: { base: "v8_cordon", n: "Тасовщик", g: "m",
    desc: "Машина привода, что ездит вместе с секциями: когда круг поворачивается, она оказывается там, где вы. Прикрывает полем машин вокруг и возникает рядом без шагов — только лязг рельса. Поле проседает на перезарядке.",
    mult: 5, beh: ["ranged", "shieldally", "blink"], rng: 5, snd: "shieldbot", sndRate: 0.65 },
  v8_b_gearkeeper: { base: "v8_mender", n: "Смотритель привода", g: "m",
    desc: "Ремонтная машина, что веками смазывала шестерни тасовки. Чинит соседних машин, сама затягивает вмятины и зовёт подборщиков. Ионы и шок сбивают её с ремонта.",
    mult: 6, beh: ["chase", "healer", "summon", "regen"], snd: "repairbot", sndRate: 0.7, minion: "v8_picker" },
  v8_b_answer: { base: "v8_proto", n: "Прототип «Ответ»", g: "m",
    desc: "Прототип, которого учили отвечать ударом на удар: часть урона он возвращает обратно, а к оружию привыкает за пару попаданий. Не стреляйте в него долго из одного ствола. Ключ-карта вклёпана в его грудной щит.",
    mult: 5, beh: ["chase", "adapt", "reflect"], snd: "android", sndRate: 1.0 },
  v8_b_modeler: { base: "v8_rigger", n: "Модельщик", g: "m",
    desc: "Машина модельной: собирала маленькие копии всего, что потом строили большим. В бою собирает лёгкие турели и выпускает дронов-иглачей. Её выдаёт стук деревянных моделей, которые она таскает с собой. Ключ-карта — в коробке с моделями.",
    mult: 5, beh: ["ranged", "builder", "summon"], rng: 4, snd: "sapper", sndRate: 1.35, minion: "v8_dart" },
  v8_b_commandant: { base: "v8_brigadier", n: "Комендант", g: "m",
    desc: "Бывший комендант общежития, переделанный за то, что прятал детей от тасовки. Порядок он помнит до сих пор: строит переделанных, обходит с флангов и зовёт подмогу. Считает своих вслух, и по счёту его слышно за две двери.",
    mult: 5, beh: ["chase", "dooropen", "commander", "summon"], snd: "labmut", sndRate: 0.7, minion: "v8_remade" },
  v8_b_capsulist: { base: "v8_seer", n: "Капсульщица", g: "f",
    desc: "Та, что надевала браслеты, — пока однажды не надели ей. Слышит вас сквозь стены, бьёт по нервам и метит, а по её шёпоту приходят кислотники. Поёт на одной ноте, как щелчок замка, растянутый на минуту.",
    mult: 5, beh: ["ranged", "psi", "marker", "summon"], rng: 5, snd: "phase", sndRate: 0.95, minion: "v8_spitter" },
  v8_b_descent: { base: "v8_walker", n: "Шагоход «Спуск»", g: "m",
    desc: "Шагоход, построенный для Трещины: шесть ног, якоря, трос на сто пролётов. Ушёл вниз с Зинаидой Глотовой и вернулся без неё — и с тех пор ходит у края, туда и обратно. Бьёт с разгона, топот сносит соседние клетки, вмятины затягиваются сами. Ключ-карта — в пустой кабине.",
    mult: 7, beh: ["chase", "charge", "splash", "regen"], rng: 2, snd: "titan", sndRate: 0.65 },
  v8_b_lastlead: { base: "v8_leader", n: "Ведущий последнего опыта", g: "m",
    desc: "Машина, назначенная вести опыт, который так и не кончился: спуск в Трещину. Командует машинами стенда, прикрывает их полем и зовёт щитоносцев. Бормочет номер опыта — один и тот же, века подряд. Ключ-карта — в его планшете.",
    mult: 6, beh: ["ranged", "commander", "shieldally", "summon"], rng: 5, snd: "android", sndRate: 0.65, minion: "v8_cordon" },
  v8_b_pakhomov: { base: "v8_seer", n: "Еремей Пахомов, опыт номер один", g: "m",
    desc: "Основатель корпуса. Первый опыт он поставил на себе — чтобы услышать Трещину, — и услышал. Слышит вас сквозь стены, бьёт по нервам, возникает рядом и зовёт переделанных. Между ударами диктует журнал. Ключ-карта — закладкой в его журнале.",
    mult: 7, beh: ["ranged", "psi", "blink", "summon"], rng: 5, snd: "phase", sndRate: 0.7, minion: "v8_remade" }
} });

/* ── КАРТОЧКИ ТВАРЕЙ голосом Опытника и ВСПЫШКИ ПАМЯТИ (мнемоник) ── */
D({ deep: {
  cards: {
    v8_intaker: "Приёмщик. Машина приёмки, охрана. Захват замедляет образец. Слабость — гидравлика захватов: ионы, ЭМИ. Рекомендация образцу: на ленту не вставать.",
    v8_leader: "Ведущий опыта. Распорядитель: рядом с ним машины умнее и злее. Слабость — голосовой узел и планшет: ЭМИ. Выведен из опыта — машины сбиваются с толку. Отметить: образцы всегда начинают с него.",
    v8_picker: "Подборщик. Уборка после опытов. Безвреден, пока не тронут; доносит. Слабость — всё. Рекомендация: не попадаться. Или не оставлять ему времени доложить.",
    v8_sphere: "Сфера-самописец. Мой глаз и ухо. Не стреляет — записывает. Тихий шаг пропускает. Разбить можно; запись об этом сохранит соседняя сфера.",
    v8_mender: "Наладчик стендов. Чинит машины в ходе опыта, первым выходит к отключённым турелям. Слабость — ионы, шок. Рекомендация: если машин больше двух, начинать с наладчика.",
    v8_rigger: "Сборщик стендов. Ставит лёгкие турели, пока цел. Слабость — ЭМИ, ионы. Пока стучит гайковёрт, опыт усложняется.",
    v8_turret: "Стендовая турель. Бьёт по прямой, отключается с терминала безопасности. Перед очередью меняет ствол — щелчок барабана. Образцы, которые слушают щелчок, живут дольше. Отметить.",
    v8_walker: "Шагоход «Проба». Тяжёлый, четыре опоры. Разгон, удар, топот по соседним клеткам. Слабость — открытые колени: ионы, шок. Пули почти бесполезны. Не стоять на прямой.",
    v8_strider: "Шагоход-разведчик. Слышит шаги через весь этаж, стреляет на ходу. Слабость — колени и электроника: ЭМИ, ионы. Песок и тасовка его путают.",
    v8_proto: "Обучаемый прототип. Привыкает к оружию за два-три попадания. Рекомендация: менять оружие. Нано и ЭМИ портят ему память. Лучший образец арсенала. Был.",
    v8_cordon: "Щитоносец оцепления. Полем прикрывает машин рядом. Выводить первым. Поле проседает на тон при перезарядке. Слабость — ЭМИ.",
    v8_modder: "Переделочный автомат. Иглы с мутагеном: яд, сковывание. Держать дистанцию. Слабость — шок, холод. Образцы с гасителем в кармане выживают чаще. Отметить без удовольствия.",
    v8_dart: "Дрон-иглач. Стайка, иглы издали, уколы травят. Хрупок: одного попадания хватает. Считать по писку — у каждого своя нота.",
    v8_sapper: "Минёр-испытатель. Ставит мины в проходах. Писк взвода — предупреждение, которое я не отменил. Слабость — ЭМИ, ионы.",
    v8_porter: "Подносчик капсул. Курьер. Раненый — бросается и лопается облаком мутагена. Бить издалека. Его груз числится в журнале. Вы — нет.",
    v8_nurse: "Сиделка коконника. Машина, лечит тварей рядом, машин не чинит. Пока цела, гнездо не умирает. Выводить раньше матки. Слабость — ионы, шок.",
    v8_hatchling: "Вылупок. Ступень разума — нулевая. Ранг — низший. Стая, голод, ест павших и крепнет. Слабость — жар. Рекомендация: не оставлять павших рядом с ними.",
    v8_reject: "Расползень. Ступень разума — нулевая. Ранг — средний. Переделка не удалась. Слеп, идёт на шум. Погибая, делится надвое. Слабость — жар, плазма: сожжённое не делится.",
    v8_overgrown: "Перегруз. Ступень разума — нулевая. Ранг — высший. Выращен под давлением, плотен. Бьёт с разгона. Пули вязнут. Слабость — жар, плазма. Хороший результат стендов. Не для образца.",
    v8_cullhound: "Браковая гончая. Ступень разума — первая. Ранг — средний. Бурая из вивария, переделанная в ловчую. Идёт по следу через этаж, лаем скликает свору. Резина и песок глушат след, тасовка его путает.",
    v8_spinner: "Коконопряд. Ступень разума — первая. Ранг — средний, каста — ткач. Плюётся липкой нитью, ставит растяжки. Слушать звон натянутой нити. Слабость — огонь.",
    v8_remade: "Переделанный. Ступень разума — вторая. Ранг — средний, каста — воин. Открывает двери, зовёт своих. Говорит «я не нарушал». Нарушал. Слабость — плазма, ингибитор.",
    v8_spitter: "Кислотник. Ступень разума — вторая. Ранг — средний, каста — стрелок. Плюётся кислотой, разъедает броню. Перед плевком булькает. Слабость — жар, ингибитор.",
    v8_brigadier: "Бригадир переделанных. Ступень разума — вторая. Ранг — высший, каста — вожак. Рядом с ним переделанные держат строй и обходят с флангов. Выведен — отряд теряется. Слабость — плазма.",
    v8_seer: "Наводчица. Ступень разума — третья. Ранг — высший, каста — провидица. Слышит образец сквозь стены, наводит отряд, бьёт по нервам, метит. Лучший слух корпуса — после вашего. Слабость — плазма.",
    v8_queen: "Матка коконника. Ступень разума — третья. Ранг — вершина, каста — матка. Неподвижна, рожает вылупков, лечит своих, бьёт по нервам. Пока гудит — гнездо спит. Слабость — жар. Сиделку — первой."
  },
  memories: [
    { t: "Опыт номер один", x: "Скрип пера, ровное дыхание, звон стекла о стекло. Мужской голос диктует сам себе, спокойно, как рецепт: «Запись. Опыт номер один. Материал — я. Доза — полная. Пульс — восемьдесят». Щелчок шприца. Долгая пауза, и дыхание становится другим — глубже и медленнее. «Слышу. Слышу её. Она не поёт — она зовёт. Пульс… не помню. Пишите вы». И перо скрипит дальше, уже без него." },
    { t: "Первый шаг", x: "Огромный зал, сотни голосов, и все вдруг стихают. Гудят насосы, шипит гидравлика, что-то тяжёлое переносит вес с опоры на опору, и пол под толпой вздрагивает. Удар. Ещё удар. Женский голос из кабины хохочет и кричит: «Пошёл! Слышите — пошёл сам!» Толпа взрывается рёвом, кто-то свистит, кто-то плачет. А машина делает третий шаг и останавливается, будто прислушивается к собственному весу." },
    { t: "Щелчок", x: "Звон половника о котёл, очередь, шарканье ботинок. Женский голос шёпотом: «Гриша, держи, ешь быстро, пока никто…» Тихий щелчок браслета — сухой, как сломанная спичка. Очередь замирает. Голос из рупора, ровный, без злости: «Норма нарушена. Нарушитель выбрал нарушение сам. Следовательно, доброволец». Где-то падает миска. Мальчик спрашивает: «Мама, что щёлкнуло?» Она отвечает очень спокойно: «Ничего. Ешь»." },
    { t: "Тасовка в ноль-ноль", x: "Колокол — три удара, низких, с оттяжкой. Скрежет катков под полом, и комната начинает медленно плыть, как лодка. Женский голос, тихий и ровный: «Держись за меня. Считаем шаги, как бабушка учила. Раз. Два. Три». Детский голос повторяет за ней. Лязг стыков, удар, тишина. «Мама, где мы?» — «Не знаю. Но мы вместе, и нас двое. Это мы знаем точно»." },
    { t: "Вечерний выпуск", x: "Шорох эфира, щелчок тумблера. Женский голос, чуть охрипший к ночи: «Говорит корпус. Вечерний выпуск. Сегодня в журнал внесено сто двенадцать замеров — это вам скажет Опытник. А я скажу имена». И она читает, медленно, по одному: имена тех, кто сегодня прошёл стенды, и тех, кто не прошёл. Динамики трещат, кто-то стучит в стену, требуя замолчать. Она дочитывает до конца." },
    { t: "«Спуск» уходит", x: "Лязг якорей, гул лебёдок, звон цепей, уходящих вниз. Гидравлика вздыхает шесть раз — шесть ног встают на край. Женский голос по проводу, сквозь треск: «Иду. Трос держит. Глубже… поёт. Здесь всё поёт. Не ждите меня к ужину». Треск становится громче, голос — тише. «Если «Спуск» вернётся пустым — значит, дальше я пешком». Щелчок. Только цепи ещё долго звенят." },
    { t: "Колыбельная шёлку", x: "Тепло, влажно, шорох шёлка со всех сторон. Женский голос напевает без слов, на одной ноте, и коконы вокруг отвечают глухим ровным стуком. Потом голос говорит — ласково, как детям: «Спите. Вам надо дорасти. Я тоже дорасту, я обещала». Где-то булькает чан. Пение продолжается, становится всё ниже и шире, пока не перестаёт быть похожим на человеческий голос." },
    { t: "Список на стене", x: "Глухо и мягко: войлок и матрасы съедают эхо. Мужской голос, усталый: «Перекличка. Не номера — имена». И из темноты отвечают: «Харитон — здесь». «Лада — здесь». «Тиша — здесь». Кто-то царапает гвоздём по стене, вписывая новую строку. «А новенький?» — «Не помнит, как звали. Только номер». — «Тогда пиши номер. Пока не вспомнит — это и есть имя». Гвоздь скрипит ещё раз." }
  ]
} });

