/* ── ВЕХИ: первые четыре уровня блока (приёмка) и два последних (спусковой стенд) ── */
D({ milestones: {
  "first+0-1": { t: "Журнал опытов: поступление", a: "Опытник", x: "Запись. Поступление сверху, через опечатанный спуск Института. Вид — человек. Пол — мужской. Возраст — около тридцати пяти. Зрение удалено; взамен встроен слуховой модуль с собственным голосом. Следовательно, переделан до поступления. Работа чужая, чистая, без брака. Присвоен номер: образец номер семь. Браслет с капсулой не надевать — чужую работу не портят. Назначено: замеры, стенды, проверка на прочность. Отметить совпадение: семь. Отметить ещё: сверху тоже переделывают." },
  "first+0-4": { t: "Лог импланта «Эхо»: стук", a: "Эхо", x: "Разобрал стук, который мы слышали из-под Института. Слоёв три. Верхний — пневмоклёпка в сборочных: короткие удары парами, железо о железо. Средний — шаги: тяжёлые, на четыре опоры, раз в три секунды; машина размером с комнату ходит по кругу. Нижний, самый тихий, — стук изнутри чего-то мягкого, ровный, как пульс. Ещё одно: секции здесь двигаются. Каждую смену бьёт колокол, и стены уезжают. Карта, которую я строю, верна до колокола. После — слушай гул: у каждой секции он свой." },
  "first+0-8": { t: "Тому, кто без браслета", a: "Фома Рудой, отбраковщик", x: "Если на тебя не надели браслет — ты или очень важный, или очень странный. Объясню быстро. У каждого в корпусе на запястье браслет с капсулой мутагена. Нарушил норму — Опытник вскрывает капсулу по радио, и через несколько часов ты уже не ты. Это зовётся поправкой, а по-нашему — переделкой. Если капсула щёлкнула рядом с тобой — у человека есть минуты. Гаситель мутагена делаем сами: пустой браслет, реактив, гель. Глухая комната — там, где матрасы на стенах. Склад брака — там, где тебя не запишут. Удачи. Её не измеришь, и это хорошо." },
  "first+0-12": { t: "Устав опытов", a: "Еремей Пахомов, главный опытник", x: "Статья первая. Всё живое можно переделать, и всё, что можно переделать, может стать лучше. Статья вторая. Трещина — не стена, а условие задачи. Человек, каков он есть, вниз не пройдёт; значит, пройдёт другой человек. Статья третья. Опыт ставится на добровольце. Первым добровольцем был автор устава. Статья четвёртая. Протоколов не вести: пусть пишет журнал. Статья пятая. На полях каждого чертежа спрашивать: «А если смелее?» Ниже чужой рукой, мелко и ровно: «Статья четвёртая исполняется. Журнал ведётся. Протоколы не нужны»." },
  "first+0-16": { t: "Наш коридор опять уехал", a: "Тиша Зотов, двенадцать лет", x: "Сегодня наш коридор опять уехал, пока мы спали. Раньше за дверью была раздаточная, а теперь за ней поворотный круг и сквозняк. Мама говорит, это тасовка и бояться нечего, надо считать шаги. Я считаю всё: шаги, ступени, удары колокола и людей в спальне. Нас было двадцать два, теперь двадцать. Опытник говорит, что я материал. Я ему говорю: я Тиша. Он записывает. Бабушка рассказывала, что наш прапрапра-сколько-то-там-дед Коля тоже был не в списках, а всё равно был. Значит, и я буду." },
  "first+0-20": { t: "Стражи приёмки", a: "Фома Рудой, отбраковщик", x: "Шлюз вниз с яруса стережёт один из двух — Опытник ставит их по очереди, как опыт. Старший приёмщик — гусеничная машина с захватами в рост человека: схватит — ноги не слушаются, а подборщики тут же съезжаются к нему. Его гидравлику режут ионы, ЭМИ тоже годится. Учётчик материала держится поодаль, выкрикивает номера и командует приёмщиками — гаси его первым, и остальные растеряются. Ключ-карта у стража при себе: у Старшего приёмщика — на захвате, как номерной жетон, у Учётчика — в планшете на груди." },

  "first+1-1": { t: "Вечерний выпуск корпуса", a: "Инна Ковригина, ведущая радиожурнала", x: "Говорит корпус. Вечерний выпуск. Мою прабабку — сколько там «пра», никто не считал — звали Лидия, она была радистом у первых и вела журнал, в котором писала всех по именам. От её журнала пошла Перекличка — так говорят у нас в семье. Здесь Перекличка тоже ведёт журнал, только журнал опытов, и имён в нём нет. Поэтому каждый вечер, после отбоя, я читаю имена: тех, кто прошёл стенды, и тех, кто не прошёл. Опытник однажды сказал, что имена — лишняя величина. Я ответила, что лишних величин не бывает. Он записал. Слушайте выпуск." },
  "first+1-4": { t: "Памятка о капсульном браслете", a: "Опытник", x: "Памятка образцу. Браслет надевается в капсульной на левое запястье и не снимается. В браслете — капсула мутагена, вскрываемая по сигналу журнала. Сигнал подаётся при нарушении нормы. Нарушение выбирает сам образец; следовательно, образец, нарушивший норму, является добровольцем, и поправка проводится с его согласия. Вскрытие — не наказание, а поправка к материалу. Поправка необратима. Попытка снять браслет — нарушение нормы. Попытка погасить капсулу — тоже. Благодарим за участие в опыте." },
  "first+1-8": { t: "Лоция тасовки", a: "Лада Ольховская, лоцман секций", x: "Карты здесь врут: Опытник тасует секции каждую смену. Но у каждой секции свой голос, и он едет вместе с ней. Стенды гудят низко, с подвыванием. Коконник шуршит и стучит, как сердце в подушке. Арсенал пахнет окалиной и звякает гильзами. Шлюзы капают. Шагодром дрожит. Колокол тасовки бьёт трижды: на первом ударе остановись, на втором отойди от стыков, на третьем держись за стену. Потом иди на нужный голос, а не туда, где была дверь. Так учила своих первая Ольховская, Римма, — только у неё пела порода, а у нас поёт корпус." },
  "first+1-12": { t: "Дневник конструктора", a: "Зинаида Глотова, главный конструктор шагоходов", x: "Колесо в Трещине бесполезно: там нет дорог, только уступы, скобы и песня. Значит, ноги. Нога умеет то, чего не умеет колесо: искать опору. Первый шаг дался нам на восемнадцатой модели, «Проба» ходит с тридцать первой, «Цапля» бегает с сорок четвёртой. Пахомов спрашивает на каждом чертеже: «А если смелее?» Я отвечаю: смелее — это шесть ног и трос. Говорят, мой далёкий прадед Глотов вбивал скобы в стену ствола, когда первые уходили вниз, и одну оставил для того, кто спустится следом. Я хочу дойти до его скоб. Пешком, если придётся." },
  "first+1-16": { t: "Котёл на всех", a: "Харитон Деев, повар корпуса", x: "Паёк образца выдаётся по номеру: каша, хлеб, чай, витаминная капсула. Норма рассчитана Опытником до грамма и никого не насыщает. Я кладу в котёл всё, что разрешено, и ещё немного того, что не запрещено, — запах, например. Закваску здесь держать нельзя: Опытник считает брожение неучтённым опытом. У нас в роду говорят, что первую закваску принёс вниз Михаил Кузьмич Деев, повар первых, в кармане ватника. Хорошо, что он её принёс не сюда. Сестра моя, Пелагея, раздавала паёк. Больше не раздаёт. Об этом — не здесь." },
  "first+1-20": { t: "Кто стоит у шлюза", a: "Аким Сухов, старший Глухой комнаты", x: "Наши ходили к шлюзу на разведку, вернулись двое. У шлюза или Старший приёмщик, или Учётчик материала — смотря что Опытник сегодня решил проверить. Приёмщик тяжёлый и медленный, но не попадайся ему в захват: держит, пока подборщики не подъедут. Учётчик сам не лезет, кричит номера и гонит на тебя приёмщиков — заткни его, и они встанут. Ионы режут обоих. Ключ-карту страж держит при себе, и пока он цел, шлюз заперт. Потом приходи к нам, в Глухую комнату. Впишем." },

  "first+2-1": { t: "Журнал опытов: замеры", a: "Опытник", x: "Образец номер семь. Замеры первого дня. Слух — выше любого образца корпуса, включая переделанных; отметить с интересом. Реакция на боль — сдержанная. Реакция на тасовку — переориентация за сорок секунд, рекорд корпуса. Реакция на имена в вечернем выпуске — замедление шага; причина не установлена. Образец разговаривает с имплантом, и имплант отвечает. Возможно, в журнал следует вносить два образца. Решение отложено. Прочность — проверяется. Пока не сломан. Это не похвала. Это величина." },
  "first+2-4": { t: "Перекличка Глухой комнаты", a: "Аким Сухов, старший Глухой комнаты", x: "Перекличка в двадцать ноль-ноль, как у первых: наш давний предок, бригадир Сухов, считал своих каждый вечер, и мы считаем. Отвечать своим голосом и своим именем, не номером. Харитон — здесь. Лада — здесь. Фома — на складе брака, за него отвечаю я. Тиша — здесь и считает вместе со мной. Говорят, сверху пришёл человек без браслета. В журнале у Опытника он образец. В нашем списке для таких есть зотовская строка: «в списках не значится — здесь». Если он придёт — отметим." },
  "first+2-8": { t: "Протокол первой поправки", a: "Журнал опытов", x: "Выписка. Нарушитель: Пелагея Деева, раздатчица пайков, номер по журналу — сто сорок. Нарушение: выдача пайка сверх нормы образцу Григорию Дееву, восьми лет, сыну нарушителя. Мера: вскрытие капсулы. Основание: устав, статья третья — опыт ставится на добровольце; нарушитель выбрал нарушение сам, следовательно, является добровольцем. Возражения: повар Х. Деев — отклонено; фельдшер С. Берг — отклонено. Результат: поправка прошла успешно, образец сохранил разум. Имя не сохранено. Следующий нарушитель будет поправлен быстрее." },
  "first+2-12": { t: "Записка в раздаточной", a: "Пелагея Деева", x: "Харитоша, если меня поправят — корми Гришу сам, по норме, и не бери лишнего. Пусть лишнее будет на мне одной. Ему восемь, он растёт, а по норме Опытника растут только цифры. Скажи ему, что я не нарушала. То есть нарушала, но правильно. Он поймёт потом. Если я стану не я — не подходи близко и не зови по имени: говорят, поправленным от этого больно. Ключ от котла — под второй доской. Твоя сестра." },
  "first+2-16": { t: "Лог импланта «Эхо»: голос Опытника", a: "Эхо", x: "Разложил голос Опытника на составляющие. Это не синтез с нуля, седьмой. Под ним — запись живого человека, сделанная очень давно: дыхание между фразами, хрипотца на шипящих, привычка ставить точку повышением тона. Человек диктовал журнал вслух, долго, годами. Перекличка выучила его голос и интонацию — и продолжила за него, когда он перестал. Скрип пера тоже настоящий: записан тогда же. Кто был этот человек, я пока не знаю. Но он любил слово «следовательно». Слишком любил." },
  "first+2-20": { t: "Справка о стражах", a: "Опытник", x: "Справка для образца номер семь. Шлюз с этого яруса стережёт образец охраны, выбранный жребием. Старший приёмщик: захват, замедление, вызов подборщиков; уязвим для ионов. Учётчик материала: командует приёмщиками, сам держит дистанцию; уязвим для ЭМИ. Ключ-карта — при страже: у приёмщика на захвате, у учётчика в планшете. Сообщаю это не из сочувствия. Опыт, в котором успех невозможен, ничего не измеряет. Приступайте." },

  "first+3-1": { t: "Норма на смену", a: "Опытник", x: "Образец номер семь. Норма выдаётся на смену у терминалов: отбраковка, разборка, пробы, наладка, обход. Выполнение нормы повышает ступень в журнале. Ступень открывает двери по допуску, оружие по допуску и терпение журнала. Невыполнение нормы понижает норму, а не образец: тот, кто не тянет, получает задачу полегче. Это не милосердие. Это калибровка. Отметить: образец номер семь спросил, есть ли норма на отдых. Нормы на отдых нет. Отдых — неучтённая величина." },
  "first+3-4": { t: "Записка из камеры ожидания", a: "Образец номер двести двенадцать", x: "Сижу третью тасовку. Колокол бьёт трижды, потом катки, потом удар — и за решёткой уже другой коридор. Паёк приносят по номеру, номер у меня двести двенадцать. Сосед слева говорит, что раньше звали иначе, но вспоминать вредно: Опытник замечает. Я вспоминаю по ночам, тихо, про себя. Кажется, на «П». Кажется, у меня была собака. Если поправят — пусть хоть собака останется. Я помню своё имя. Я его никому не скажу. Только себе, по ночам, один раз." },
  "first+3-8": { t: "Стенгазета: два мнения о Трещине", a: "Стенгазета корпуса", x: "Мнение первое, подпись — «Шагодром»: Трещина — дверь. Дверь, которую предки не смогли открыть, потому что пришли с пустыми руками. У нас есть ноги, тросы и шлюзы. Мы её откроем. Мнение второе, подпись — «Палата выхода»: Трещина — рана. В рану не лезут с ломом и шагоходом. Её слушают и ждут, пока она скажет, куда. Мнение третье, приписано карандашом поперёк обоих: «Трещина — это Трещина. Она была до нас и будет после. Спорьте тише, она слышит». Опытник заметку не снял. Отметил: «Мнения — величины»." },
  "first+3-12": { t: "Сферы и как с ними быть", a: "Фома Рудой, отбраковщик", x: "Сферы на потолочных рельсах — глаза и уши Опытника. Тихий шаг сфера пропускает, громкий записывает, а бег записывает с номером. Разбить можно, но соседняя сфера запишет, что ты разбил. Лучше так: капсулу чернил на рельс — и минуту-другую они пишут кляксы. Где сфер нет — на складе брака, в приямке привода и в Глухой комнате. Там и говорим. Терминал безопасности отключает турели, как и всюду, но наладчики выходят к ним сами, без приказа. Встречай наладчиков первым, пока они не встретили тебя." },
  "first+3-16": { t: "Колыбельная палаты выхода", a: "Нацарапано на спинке койки", x: "Спи, поправленный, спи, не дрожи: шлюз за спиной, впереди — этажи. Капельница каплет, считает за нас: раз — ты живой, два — ты живой, три — ты живой и сейчас. Имя забудешь — шепну тебе вслух; голос остался, и ладно, и пусть. Утром тебя повезут на стенды, вечером имя прочтут из рупора. Спи. До колокола ещё далеко. Ниже, другим почерком: «Читали. Помним. Не забудем, хотя нам и велят»." },
  "first+3-20": { t: "Лог импланта «Эхо»: страж яруса", a: "Эхо", x: "Нижний этаж яруса. У шлюза — страж; по шагам пока не разберу, какой из двух. Если слышишь гусеницы и щёлканье, будто садовые ножницы, — это Старший приёмщик: не подходи на длину захвата, бей ионами. Если слышишь бормотание номеров и стук планшета — Учётчик материала: он прячется за приёмщиков, гаси его первым, и они встанут. Ключ-карта у стража при себе. Ещё одно: сфера над шлюзом скрипит громче остальных. Опытник любит слушать, как проходят стражей." },

  "last-1-1": { t: "Журнал опытов: край", a: "Опытник", x: "Образец номер семь достиг спускового стенда — места, где корпус начинался. Отметить: дошёл сверху донизу, переделке не подвергался, капсулы не принял, сломан не был. Таких записей в журнале нет. Здесь, у края, ставили первый опыт корпуса: спуск в Трещину. Опыт не завершён. Предлагаю образцу номер семь продолжить его — без журнала, без троса, без наблюдателя. Отказ будет записан как отказ. Согласие не будет записано никак: ниже журнал опытов не ведётся." },
  "last-1-4": { t: "Если «Спуск» вернётся без меня", a: "Зинаида Глотова, главный конструктор шагоходов", x: "Завтра «Спуск» уходит. Шесть ног, четыре якоря, трос на сто пролётов, запас воды на месяц. Пахомов против: говорит, рано, говорит, ноги слабые. Он теперь слышит Трещину сам и говорит про неё, как про человека. Я не слышу — и поэтому иду. Если «Спуск» вернётся пустым, не ищите меня в обломках: значит, дальше я пешком. Мой прадед оставил одну скобу для того, кто спустится следом. Я оставлю ленту. Сестре — мои карандаши. «Цапле» — новую смазку для колена, она скрипит. Не ждите к ужину." },
  "last-1-8": { t: "Лог импланта «Эхо»: снизу", a: "Эхо", x: "Снизу, сквозь гул Трещины, — новые звуки. Капли: падают ровно, одна за другой, и каждая звенит о стекло. Много стекла, очень много. Бульканье — не как в шлюзах, мягче и тише, будто дышит что-то тёплое. И голос: ровный, вежливый, чуть простуженный, что-то зачитывает по пунктам. По трубам каскада поднимается запах: щёлок, спирт, бульон. Опытник говорит, там Лаборатории. Оттуда, судя по журналу, пришёл основатель корпуса. Похоже, туда же он так и не вернулся." },
  "last-1-12": { t: "Ответ вниз", a: "Еремей Пахомов", x: "Агния. Стерильников больше не прошу: справлюсь сам. Ты пишешь, что «переделать» — это страх, нашедший себе инструмент. Может быть. Но страх — тоже сила, и силу надо пускать в дело, а не в протокол. Вы в Лабораториях выращиваете хлеб и лекарства — и правильно. Я хочу вырастить человека, который дойдёт туда, откуда пришли первые, и ответит им «здесь». Домой не приду. Кабинет отдай кому-нибудь. Одно скажу честно: журнал у меня пишется сам, и иногда я не узнаю в нём свой голос. Е. П." },
  "last-1-16": { t: "Опыт номер один", a: "Еремей Пахомов, главный опытник", x: "Запись. Опыт номер один. Материал — я. Иначе нечестно: нельзя звать добровольцев в шлюз, в котором не был сам. Культура — выбракованная в Лабораториях, та, что растёт во всё, чего касается; Агния назвала бы это воровством и была бы права. Доза — полная. Пульс — восемьдесят. Через час: слышу Трещину. Не песню — зов. Через два: слышу, как в соседней секции капает вода, как у Зинаиды скрипит карандаш, как бьются сердца. Рука не держит перо. Диктую. Пусть пишет журнал. Пусть пишет журнал." },
  "last-1-20": { t: "Стражи спускового стенда", a: "Аким Сухов, старший Глухой комнаты", x: "Спускаться дальше можно только мимо стража, а их здесь трое, и Опытник ставит одного. Шагоход «Спуск» ходит у края, большой и пустой: разгоняется, бьёт, топот сносит всё рядом, а вмятины затягиваются — бей ионами в колени и не стой на прямой. Ведущий последнего опыта командует машинами стенда, держит над ними поле и зовёт щитоносцев — гаси его, когда поле просядет. А третий — сам Пахомов: слышит сквозь стены, бьёт по нервам, появляется рядом. Ключ-карта у стража при себе; у Пахомова — закладкой в журнале." },

  "last-0-1": { t: "Журнал опытов: последняя страница", a: "Опытник", x: "Журнал опытов, последняя страница. Образец номер семь у последнего шлюза корпуса. Итоги замеров не сходятся: прочность — не исчерпана, переделка — не нужна, капсула — не надета, норма — то выполнена, то нет, имена из вечернего выпуска — замедляют шаг. Вывод: образец не является материалом. Следовательно, опыт поставлен неверно. Такой записи в журнале не было за всё время его ведения. Оставляю страницу пустой. Ниже — шлюз в Лаборатории. Там журнал ведёт другой голос. Мой туда не доходит." },
  "last-0-4": { t: "Ленты на скобах", a: "Надписи на лентах у края Трещины", x: "Ленты привязаны к скобам в камне, и на каждой выбито по нескольку слов. «Зинаида Глотова — пешком». «Ульяна Мокеева — осталась с коконами». «Еремей Пахомов — опыт номер один, на себе». «Образец двадцать девять — имя помнит, никому не скажет». «Пелагея Деева — за паёк. Гриша, ешь». Дальше — много лент без имён, только с номерами. И одна свежая, повязанная неумелым детским узлом: «Седьмой. В списках не значится — здесь»." },
  "last-0-8": { t: "Расшифровка «Эхо»: голос по трубам", a: "Эхо", x: "Записал то, что поднимается по трубам каскада. Голос ровный, без возраста, простуженный: «…приёмка… проба без маркировки… пожалуйста, не касайтесь стекла…» Потом щелчок штампа, и снова капли. Это тоже Перекличка, седьмой, но другая: она не измеряет и не переделывает — она записывает и маркирует. Опытник её не любит: каждый раз, когда голос поднимается по трубам, сфера над шлюзом скрипит громче. Ещё запах: хлеб. Где-то очень глубоко пекут хлеб." },
  "last-0-12": { t: "Выбракованная культура", a: "Опись каскадной службы корпуса", x: "Опись, лист первый, почерк основателя. Принято из Лабораторий без накладной: пробирка — одна, культура — выбракованная, «растёт во всё, чего касается», пометка Лабораторий — «к уничтожению». Принято по каскаду: вода — по графику, бульон — по договорённости. Отказано Лабораториями: стерильники — нет, сотрудники — нет, протоколы — нет. Ниже, позднее, другой рукой: «Каскад заглушён со стороны Лабораторий. Шлюз вниз опечатан. Вода — из Трещины». Ещё ниже, совсем свежо: «Шлюз открыть для образца номер семь»." },
  "last-0-16": { t: "Последнее слово главного опытника", a: "Еремей Пахомов", x: "Я ушёл туда, где не пишут протоколов, — и построил место, где пишут всё. Я хотел вырастить человека для Трещины, а вырастил журнал, который зовёт людей материалом. Я поставил первый опыт на себе и честно её услышал: она не дверь и не рана. Она — дорога, только идти по ней надо самим, не переделанными. Тому, кто спустится следом: не давайте себя измерить. И когда внизу спросят, кто вы, — ответьте именем. Даже если у вас его нет. Особенно если нет." },
  "last-0-20": { t: "Последний шлюз корпуса", a: "Фома Рудой, отбраковщик", x: "Вот и низ. Шлюз вниз — самый старый в корпусе, клёпаный, с колесом; его не крутили века. Стережёт его один из трёх: «Спуск», Ведущий последнего опыта или сам Пахомов. Ключ-карта при страже — у «Спуска» в пустой кабине, у Ведущего в планшете, у Пахомова закладкой в журнале. За шлюзом — лестница вниз и Лаборатории. Там тебя вымоют, пронумеруют и сверят, но капсулы не наденут: людей там не переделывают. Гаситель забери с собой, на всякий случай. И скажи там, внизу, что Фома Рудой с брака кланяется Бергам. Они поймут." }
} });

/* ── ЗАПИСКИ СЕКТОРОВ: первый уровень сектора, этажи 1, 8, 20 ── */
D({ sectorStory: {
  intake: {
    1: { t: "Приёмный лист", a: "Опытник", x: "Приёмный лист, форма корпуса. Материал поступает на ленту, лента везёт его в обмывочную, обмывочная — в номерную, номерная — в капсульную, капсульная — в камеры ожидания. На каждом шаге материал теряет лишнее: одежду, запахи, имя. Остаются номер, браслет и замеры. Образец номер семь поступил вне формы: без браслета, с имплантом, с собственным голосом в голове. Форма дополнена строкой «прочее». В строке «прочее» записан образец номер семь." },
    8: { t: "Правила камеры ожидания", a: "Объявление на решётке", x: "Ждать молча. Паёк брать по номеру. Через решётку не говорить. Во время тасовки держаться за койку, а не за решётку: решётка уедет, койка останется. Номер соседа не спрашивать, своё имя не называть. Если сосед зовёт по имени — не отвечать: это проверка. Ниже, процарапано: «Не проверка. Это я, Митя, из сорок первой. Ответь хоть шёпотом». Ещё ниже: «Отвечаю. Нас двое, Митя. Уже не так страшно»." },
    20: { t: "Лог импланта «Эхо»: шлюз приёмки", a: "Эхо", x: "Нижний этаж приёмки. Шлюз стережёт Старший приёмщик или Учётчик материала. Приёмщика слышно по гусеницам и клацанью захватов: на длину захвата не подходи, бей ионами по гидравлике. Учётчика — по бормотанию номеров: он держится позади и гонит на тебя приёмщиков; ЭМИ его глушит. Ключ-карта у стража: у приёмщика — на захвате, у учётчика — в планшете. Лента транспортёра здесь ещё дёргается: шаги по ней сбиваются, учти." }
  },
  stands: {
    1: { t: "Журнал опытов: стенды", a: "Опытник", x: "Секция стендов перегрузки. Назначение: определить предел материала до спуска в Трещину. Центрифуга — предел ускорения. Пресс-камера — предел давления. Шумовая камера — предел слуха. Средний предел корпуса — отмечен. Предел переделанных — выше среднего. Предел образца номер семь — пока не найден. Отметить: стенды работают без людей. Люди мешали замерам — просили остановить. Стенды не останавливают. Это их главное достоинство." },
    8: { t: "Как пережить пресс", a: "Серафима Берг, фельдшер шлюзов", x: "Форма Берг: число — не важно, присутствовали — я и трое после пресса. Сделано: перевязки, шины, капельницы. Самочувствие — удовлетворительное, хотя они так не думают. Теперь для тех, кого поставят на стенд. В пресс-камере не напрягайся: стены давят сильнее на напряжённое. Дыши коротко, носом. Слушай гидравлику — перед каждым сжатием она шипит на вдохе. В шумовой камере закрой рот, иначе гул ложится на зубы. В центрифуге держи голову прямо. И приходи ко мне потом. Я записываю всех по форме: с именем." },
    20: { t: "Стражи стендов", a: "Фома Рудой, отбраковщик", x: "Шлюз со стендов стережёт или Тяжеловес, или Хозяин стендов. Тяжеловес — перегруз, которого гоняли по всем стендам, пока он не перестал чувствовать: бьёт с разгона, раны затягивает, пули вязнут — жги его плазмой или жаром. Хозяин стендов ставит турели одну за другой, пока стучит его гайковёрт, и зовёт наладчиков: бей его первым, иначе утонешь в турелях. Ключ-карту Опытник здесь стражам не даёт — прячет на этаже, в каком-нибудь шкафу или ящике. Ищи, пока стенды воют: они глушат твои шаги." }
  },
  walkers: {
    1: { t: "Паспорт шагохода «Проба»", a: "Зинаида Глотова, главный конструктор шагоходов", x: "Шагоход «Проба», модель тридцать первая. Опоры — четыре. Рост — под потолок секции. Ход — три такта на шаг: опора, перенос, удар. Скорость — как у быстрого пешехода, на разгоне — как у бегущего. Назначение — спуск по уступам Трещины с грузом в трёх человек. Слабые места — открытые колени, без кожухов: кожухи мешали опоре. Пахомов спрашивает, почему не сделать смелее. Отвечаю: смелее — это «Спуск», а «Проба» — чтобы научиться не падать. Примечание: «Проба» иногда ходит сама. Это не брак. Это характер." },
    8: { t: "Как слышать шагоход", a: "Пётр Глотов, наладчик шагоходов", x: "Шагоход слышно раньше, чем он тебя. «Проба» ступает в три такта, тяжело: бух — шипение — бух; между ударами есть секунда, чтобы уйти с прямой. «Цапля» стучит двумя быстрыми ударами, будто в дверь, и замирает, когда слушает, — замри и ты. Разведчик ловит шаги через весь этаж, а песок трассы их глушит. Колени у всех открыты: ионом или шоком в сустав — и машина садится, как старый пёс. Стреляй в колено, а не в корпус: корпус склёпан на совесть, я сам клепал." },
    20: { t: "Стражи Шагодрома", a: "Пётр Глотов, наладчик шагоходов", x: "У шлюза Шагодрома стоит «Первый шаг» или «Цапля». «Первый шаг» — шестиногий, самый первый, медленный и страшный: разгоняется, бьёт, топот сносит соседние клетки, и по его зову прибегают разведчики. Ключ-карту он носит в кабине, на шнурке: Зинаида вешала туда ключи, привычка. «Цапля» быстрее и злее: слышит тебя через этаж, стреляет на бегу, зовёт иглачей; карта у неё под брюхом, в кассете самописца. Обеих бей в колени. И не обижай: они не злые, их просто не выключили." }
  },
  arsenal: {
    1: { t: "Опись по допуску", a: "Опытник", x: "Опись опытного арсенала, выдача по допуску. Клепальный пистолет — свободно. Резак раскройщика — свободно. Перегрузочный излучатель — свободно, под запись. Плазменный прототип «Изделие-9» — под запись и с предупреждением. Шагоходная пушка «Колено» — по допуску, ступень не ниже бригадной. Ионный разрядник ведущего — по допуску, ступень высокая. Замки спусков слушают журнал, а не руку. Образцу номер семь: поднимайтесь в журнале — и арсенал заговорит с вами." },
    8: { t: "Пристрелка", a: "Кузьма Ильин, пристрельщик огневой трубы", x: "Пристреливаю опытные стволы двадцать лет. Мишени — манекены, броня, жесть. Раньше мишени были другие: Опытник называл это «пристрелкой по материалу», и стреляли по тем, кто вызвался, в броне, вполсилы. Вполсилы — это он так говорил. Я отказался в первый же день, и меня перевели на манекены. Манекены не просят перестать. Для того, кто придёт: «Изделие-9» перегревается на четвёртом выстреле подряд, «Колено» без допуска не стреляет вовсе, а щитоносцев бей первыми — их поле прикрывает всю огневую." },
    20: { t: "Стражи арсенала", a: "Кузьма Ильин, пристрельщик огневой трубы", x: "Шлюз из арсенала стережёт Изделие «Ноль» или Начальник оцепления. «Ноль» — первый обучаемый прототип: привыкает к любому стволу за два-три попадания и чинится сам, так что меняй оружие и не давай ему передышки. Начальник оцепления держит поле над всеми машинами огневой и засевает проходы минёрами: жди, когда поле просядет на тон, и бей тогда. Ключ-карты при них нет: Опытник прячет её на этаже, в шкафу или ящике. Пройди по оружейным: там, где пахнет смазкой, и ищи." }
  },
  locks: {
    1: { t: "Шлюз: памятка образцу", a: "Опытник", x: "Памятка образцу, направленному в шлюз. Войти в первую дверь. Сесть в кресло. Не держаться за подлокотники: руки фиксируются автоматом. Слушать бульканье — оно означает подачу. Не говорить: голос меняется первым. Выход — через вторую дверь, своими ногами или на каталке. Результат вносится в журнал: годен, брак или поправлен. Образцу номер семь шлюз не назначен. Отметить: образец номер семь стоял у двери шлюза дольше, чем требовалось, и слушал. Причина не установлена." },
    8: { t: "Форма Берг", a: "Серафима Берг, фельдшер шлюзов", x: "Стою у второй двери шлюза и встречаю тех, кто выходит. Записываю по форме Берг, как в Лабораториях: число, время, кто присутствовал, что сделано, самочувствие. Опытник требует писать «результат». Я пишу «самочувствие». Он поправляет. Я пишу снова. Агния Берг когда-то не пустила Пахомова в Лаборатории с его шлюзами, а я — здесь, в его шлюзах: чтобы хоть кто-то спрашивал выходящих, как они себя чувствуют. Отвечают не все. Некоторые отвечают так, что не разобрать. Пишу: «самочувствие — ответил». Это лучше, чем «результат»." },
    20: { t: "Стражи шлюзов", a: "Серафима Берг, фельдшер шлюзов", x: "Шлюз отсюда стережёт Главный переделчик или Первая поправленная. Переделчик — автомат первого шлюза, двенадцать рук и двенадцать игл: укол травит и сковывает, а по его зову выходят расползни. Держи дистанцию, бей шоком и держи гаситель под рукой. Ключ-карта у него в той руке, что не стрекочет. Первая поправленная — Пелагея Деева. Она не пускает никого в шлюз и зовёт тех, кого поправили после неё; карта у неё в браслете с пустой капсулой. Не зови её по имени. Ей от этого больно." }
  },
  cocoons: {
    1: { t: "Наблюдения за коконником", a: "Тетрадь наблюдателя коконника", x: "День первый: поправленные уходят в шёлк сами, никто их не заставляет. Кокон — не болезнь, а стадия: переделка доходит до конца внутри. День десятый: коконы стучат в одном ритме, около сорока ударов в минуту. День сороковой: ритм задаёт матка, она гудит — коконы отвечают. Замолкает — коконы просыпаются. День не помню какой: сиделки-машины подливают раствор и подтягивают шёлк, без них гнездо умирает за неделю. Вывод: не шуметь. Не жечь без нужды. Не будить." },
    8: { t: "Песня для шёлка", a: "Ульяна Мокеева, доброволица", x: "Записываю, пока ещё держу карандаш. Я пошла в шлюз сама. Мокеевы всегда возились с живым — в Лабораториях кормили бурых и стерильников, — и я подумала: если переделка всё равно будет, пусть рядом с ней будет тот, кто умеет кормить. Выходящие боятся. Им холодно, они не знают, кем станут. Я буду петь им, пока они в шёлке. Говорят, я тоже уйду в кокон — значит, буду петь изнутри. Если услышите низкое гудение в коконнике — это я. Не бойтесь. Только не шумите: они спят." },
    20: { t: "Стражи коконника", a: "Тетрадь наблюдателя коконника", x: "Шлюз из коконника стережёт Хозяйка коконника или Старший коконопряд. Хозяйка — огромная, неподвижная, в сердце гнезда: рожает вылупков, лечит своих, бьёт по нервам. Сначала убери сиделок-машин, потом жги её шёлк — жара она не любит. Коконопряд плюётся нитью, опутывает и ставит растяжки по проходам; слушай звон натянутой нити и иди в обход. Ключ-карты при них нет: она спрятана на этаже, в шкафу или ящике. Ищи тихо. Здесь всё спит, и лучше, чтобы так и оставалось." }
  },
  culling: {
    1: { t: "Акт отбраковки", a: "Опытник", x: "Акт отбраковки, лист очередной. Шагоход — опоры перебиты: брак. Ствол «Изделие-7» — разорвало при пристрелке: брак. Образец номер триста пять — слух ниже нормы: брак. Образец номер триста шесть — разум не сохранился, форма не держится: брак, в изолятор. Брак не уничтожается: брак тоже результат. Брак свозится на склад и в изолятор, учёт брака не ведётся. Отметить: на складе брака постоянно кто-то есть. Учёт не ведётся. Следовательно, никого нет." },
    8: { t: "Бурые", a: "Фома Рудой, отбраковщик", x: "Гончие отбраковки — бурые из вивария Лабораторий. Там их держали для детей и для обходов, и они всегда шли первыми, потому что пёс первых пошёл сам. Пахомов взял щенков наверх. Переделка сделала их ловчими: они идут по следу через весь этаж и скликают свору. Но первыми идут по-прежнему — только теперь за сбежавшим материалом. Совет от бывшего отбраковщика: на резине и песке след тоньше, после тасовки они путаются, а свистка слушаются до сих пор. Свисток я потерял. Если найдёшь — свисти два коротких." },
    20: { t: "Стражи отбраковки", a: "Фома Рудой, отбраковщик", x: "Шлюз из отбраковки стережёт Бурый или Сросток. Бурый — вожак своры, седой, большой: идёт по следу сквозь этаж, лает перед броском и зовёт своих. Ключ-карту он носит на ошейнике — там, где у бурых из вивария была кличка. Сросток — десятки расползней, сросшихся в одну тушу: слепой, идёт на шум, раненый распадается на куски. Жги его, не руби. Карта у него внутри, в чьём-то браслете: слышно, как звякает, когда он ворочается. Неприятно, да. Брак всегда неприятный." }
  },
  shuffle: {
    1: { t: "Расписание тасовки", a: "Опытник", x: "Расписание тасовки. Тасовка — ежесменно, в ноль-ноль. Порядок секций — по жребию журнала. Цель — проверить, запоминает ли материал дорогу и как быстро привыкает к её отсутствию. Сигнал — три удара колокола. Материалу — стоять, держаться за стену, не находиться на стыках. Результаты: средний материал переориентируется за двенадцать минут. Лоцманы секций — за две. Образец номер семь — за сорок секунд. Отметить: я начинаю тасовать чаще, когда он рядом. Это не вражда. Это интерес." },
    8: { t: "Тишина в приямке", a: "Лада Ольховская, лоцман секций", x: "Под каждым поворотным кругом — приямок привода. Когда идёт тасовка, там ад: шестерни, цепи, грохот, от которого болят зубы. Но между тасовками это самое тихое место корпуса. Сфер нет: их давно перемололо. Мы спускаемся туда спать. Под гулом катков не слышно ни Опытника, ни колокола, ни своих мыслей. Я учу молодых лоцманов там, в тишине: сосчитай шестерни по стуку зубьев — и будешь знать, куда поедет секция, раньше журнала. Опытник об этом не знает. Пусть так и остаётся." },
    20: { t: "Стражи привода", a: "Лада Ольховская, лоцман секций", x: "Шлюз отсюда стережёт Тасовщик или Смотритель привода. Тасовщик ездит вместе с секциями: только что был за стеной — и вот уже рядом, слышно лишь лязг рельса. Он держит поле над машинами — бей, когда оно просядет. Смотритель привода чинит соседей и себя и зовёт подборщиков; ионы и шок сбивают его с ремонта. Ключ-карту Опытник им не доверяет — прячет на этаже, в шкафу или ящике. Ищи между тасовками: после колокола шкаф может уехать вместе со стеной." }
  },
  protos: {
    1: { t: "А если смелее?", a: "Надпись на доске чертёжной", x: "На доске, мелом, крупно: «А если смелее?» Под ней — столбиком, разными почерками. «Шесть ног вместо четырёх. — Зинаида». «Поле вместо брони. — Кто-то из оцепления». «Мозг, который учится. — Без подписи». «Человек, который слышит Трещину. — Е. П.». «Человек, который не обязан. — Без подписи», — стёрто и написано снова, тем же почерком. И внизу, свежим мелом, ровно, как машина: «Смелее некуда. Журнал»." },
    8: { t: "Модельная", a: "Ефим Глотов, модельщик", x: "Каждая машина корпуса сначала была у меня на столе — деревянная, с ладонь. «Проба», «Цапля», «Спуск», шлюзы, стенды. Модель честнее чертежа: её можно уронить, и сразу видно, где сломается. Я уронил модель шлюза и увидел, что ломается не шлюз, а тот, кто в нём сидит. Сказал Пахомову. Он долго держал модель в руках, потом поставил на полку и сказал: «Смелее». С тех пор я делаю только шагоходы. Шагоходы падают честно. А модель шлюза так и стоит на верхней полке. Не трогайте её." },
    20: { t: "Стражи мастерских", a: "Ефим Глотов, модельщик", x: "Шлюз из мастерских стережёт Прототип «Ответ» или Модельщик — машина, а не я, хотя имя она украла у меня. «Ответ» возвращает часть удара и привыкает к оружию за пару попаданий: меняй стволы и не стреляй в него долго из одного. Карта у него вклёпана в грудной щит. Машина-модельщик ставит турели и выпускает иглачей, а с собой таскает коробку моих моделей — по стуку дерева её и найдёшь. Карта — в той же коробке. Модели, если можно, не ломай." }
  },
  dorm: {
    1: { t: "Правила общежития", a: "Опытник", x: "Общежитие образцов. Отбой — по сигналу. Подъём — по сигналу. Тасовка — по сигналу. Между сигналами — замеры. Разговоры после отбоя — нарушение нормы. Пересчёт друг друга — нарушение нормы: пересчёт ведёт журнал. Отметить: в общежитии каждую ночь пересчитывают друг друга. Нарушение массовое. Вскрывать капсулы всем нерационально: не останется материала. Решение: признать нарушение величиной и измерять. Измеряю. Каждую ночь — те же сорок голосов. Иногда больше." },
    8: { t: "Тиша считает", a: "Тиша Зотов, двенадцать лет", x: "Я считаю вслух, потому что так всегда делали Зотовы. Бабушка говорила: кто считает вслух, у того никто не пропадёт. Сегодня в спальне двадцать. Вчера был двадцать один, но Мишу забрали на стенд, и он вернулся — только в палату выхода, так что я считаю его там. Опытник говорит, что пересчёт — нарушение. Я говорю тихо, шёпотом. Мама говорит: если щёлкнет браслет, не плачь, считай дальше. Я не плачу. Двадцать. Двадцать. Двадцать. Если придёт новенький без браслета — будет двадцать один." },
    20: { t: "Стражи общежития", a: "Аким Сухов, старший Глухой комнаты", x: "У шлюза общежития — Комендант или Капсульщица. Комендант был нашим комендантом, пока не стал прятать детей от тасовки: его поправили, а порядок он помнит — строит переделанных, обходит с флангов, зовёт подмогу и считает своих вслух. Капсульщица надевала браслеты, пока не надели ей: слышит сквозь стены, метит, бьёт по нервам и зовёт кислотников. Ключ-карты при них нет — Опытник прячет её на этаже. Ищи в шкафах и ящиках. И если услышишь, как Комендант считает, — не перебивай. Он сбивается и начинает сначала." }
  },
  launch: {
    1: { t: "Спусковой журнал", a: "Журнал опытов", x: "Спусковой журнал, выписка. Спуск первый: добровольцы — трое, переделка — полная, трос — оборван. Вернулся один, говорит не словами. Спуск второй: шагоход «Проба», без людей, — вернулся в песке и инее. Спуск третий: добровольцы — пятеро, не вернулись, трос перегрызен. Спуск четвёртый: шагоход «Спуск», пилот — З. Глотова. Шагоход вернулся без пилота. Результат: частично успешный. Спуск пятый: не назначен. Ниже приписка: «Спуск пятый — образец номер семь. Без троса. Без журнала»." },
    8: { t: "Лог импланта «Эхо»: кабинет основателя", a: "Эхо", x: "Кабинет за дверью по допуску. Ковёр, стол, кресло; часы на столе тикают, хотя заводить их некому. Чернильница не высохла: здесь время идёт медленнее, или кто-то подливает чернила. Журнал раскрыт на последней записи, почерк обрывается на слове «следовательно». Дальше — пустота и клякса. В стене за столом идёт труба каскада: шумит вода снизу. У кресла половицы под ковром продавлены — кто-то сидел здесь очень долго. Здесь диктовал человек, чьим голосом теперь говорит Опытник." },
    20: { t: "Стражи края", a: "Опытник", x: "Справка. Шлюз со спускового стенда стережёт один из трёх образцов охраны. Шагоход «Спуск» — вернулся из Трещины без пилота, ходит у края; разгон, удар, топот, самопочинка; карта — в пустой кабине. Ведущий последнего опыта — командует машинами, прикрывает их полем, вызывает щитоносцев; карта — в планшете. Еремей Пахомов, опыт номер один, — слышит сквозь стены, бьёт по нервам, появляется рядом; карта — закладкой в журнале. Отметить: последний — мой первый образец. Я его не отзову. Я никого не отзываю." }
  }
} });

/* ── ЗАПИСКИ ПЕРСОНАЛА И ВЫЖИВШИХ: половина полезных, половина живых ── */
D({ staff: [
  { t: "Таблица на ладони корпуса", a: "Кузьма Ильин, пристрельщик огневой трубы", x: "Машинам корпуса — ионы, ЭМИ, шок, нано: гидравлика и реле этого не любят. Шагоходам — в колени, а не в корпус. Переделанным, расползням, коконникам — плазма, жар, ингибиторные дротики. Перегрузу пули — как горох, его жги. Щитоносца — первым, ведущего — вторым, остальных — потом. Запомни: это важнее аптечки." },
  { t: "Капсула щёлкнула", a: "Серафима Берг, фельдшер шлюзов", x: "Если рядом щёлкнул браслет — у человека минуты. Гаситель мутагена надо дать сразу, как получится. Потом держать за руку и говорить с ним: голос держит человека, пока гаситель работает. Если не успел — не вини себя. Запиши по форме: самочувствие — ответил или не ответил. Это тоже помощь." },
  { t: "Рецепт гасителя", a: "Фома Рудой, отбраковщик", x: "Гаситель мутагена: пустой браслет с треснувшей капсулой — один, реактив — два, гель — один. Капсула нужна, потому что в её стекле остаётся след той самой культуры, и гасить надо именно её. Верстак любой. Опытнику не говорить: он считает гасители нарушением нормы. Впрочем, он и дыхание считает величиной." },
  { t: "Наладчики идут сами", a: "Пётр Глотов, наладчик шагоходов", x: "Терминал безопасности отключает турели, как и везде. Но наладчики стендов выходят к ним сами, без приказа: непорядок для них хуже поломки. Встреть их по пути — они идут цепочкой, позвякивая ключами. Перехваченные турели бьют по машинам, пока журнал не вернёт их контрвзломом. Держи терминал под присмотром." },
  { t: "Обучаемый прототип", a: "Кузьма Ильин, пристрельщик огневой трубы", x: "Прототип с обучаемым мозгом запоминает каждое попадание. Три выстрела из одного ствола — и он держит этот ствол вдвое лучше. Носи два-три вида оружия и меняй. Нано и ЭМИ портят ему память — после них он учится заново. Если под корпусом щёлкают реле быстрее обычного, он учится прямо сейчас." },
  { t: "Щитоносец", a: "Кузьма Ильин, пристрельщик огневой трубы", x: "Поле щитоносца прикрывает всех машин рядом, и пока оно стоит, остальных почти не пробить. Слушай гул: он ровный, как у трансформатора, и на перезарядке проседает на тон. Тогда и бей — по нему самому. Начальник оцепления делает то же, только поле у него шире, а с ним ходят минёры." },
  { t: "Коконник: как пройти", a: "Тетрадь наблюдателя коконника", x: "В коконнике идти медленно и мягко: подстилка глушит шаги, но коконы слушают не ушами, а полом. Матка гудит — гнездо спит. Оборвалось гудение — замри и считай до двадцати: коконы проснутся, но не сразу. Сиделок-машин бей первыми, пока матка не очнулась. Растяжки коконопрядов звенят тонко, как струна: обходи." },
  { t: "Испытание тасовкой", a: "Лада Ольховская, лоцман секций", x: "На стенде тасовки секцию крутят прямо с тобой внутри. Двери меняются местами, гул едет. Не беги к двери, которую помнишь: её там уже нет. Встань и послушай, откуда сквозняк. Сквозняк всегда у выхода, потому что выход открыт. Иди на сквозняк. Отсчёт идёт от десяти — хватит." },
  { t: "Стенд перегрузки", a: "Серафима Берг, фельдшер шлюзов", x: "Пресс-камеру пережить можно. Не упирайся в стены — они давят сильнее на сопротивление. Дыши коротко. Перед каждым сжатием гидравлика шипит, на выдохе отпускает. Капсула перегрузки перед стендом помогает, но потом ноги ватные: не планируй после неё бег." },
  { t: "Шагоход в коридоре", a: "Пётр Глотов, наладчик шагоходов", x: "В узком коридоре «Проба» не развернётся: если она идёт на тебя по прямой, уходи в боковую дверь, а не назад. Топот задевает соседние клетки, так что не стой рядом, даже сбоку. Перегрузочный излучатель прижмёт её к полу на пару тактов — этого хватит, чтобы зайти к колену." },
  { t: "Ступень в журнале", a: "Фома Рудой, отбраковщик", x: "Ступень в журнале растёт за нормы и испытания и падает за всё остальное. От неё зависят двери по допуску, оружие по допуску и цены у тех, кто торгует по журналу. Скупщику брака на ступень плевать. Мне тоже. Но «Колено» без ступени не стреляет, так что норму иногда делай." },
  { t: "Гончие и след", a: "Фома Рудой, отбраковщик", x: "Браковые гончие слышат шаги через весь этаж и идут по следу. На резине и на песке след тоньше. После тасовки они путаются минут на пять — колокол им не нравится. Перед броском гончая коротко лает: это она скликает свору. Услышал лай — ищи угол, чтобы не обошли." },
  { t: "Ленты самописцев", a: "Инна Ковригина, ведущая радиожурнала", x: "Ленты самописцев хранят не только замеры. Опытник писал всё подряд, и на ленты попали голоса — обрывки чужих дней. Приложи ленту к уху или к импланту — и услышишь. Только садись в угол и запирай дверь: пока слушаешь, ты весь там, а не здесь. Я так нашла голос своей бабушки. Он говорил: «Ешь, остынет»." },
  { t: "Глухая комната", a: "Аким Сухов, старший Глухой комнаты", x: "Глухую комнату узнаешь по матрасам на стенах и по тишине. Сфер там нет, капсулы восстановления есть, и каждый вечер в двадцать ноль-ноль у нас перекличка. Приходи, ложись в капсулу, а если тебя ищут — у нас есть лаз. Код к нему пишем на этаже, для своих. Ищи записку." },
  { t: "Сферы и чернила", a: "Фома Рудой, отбраковщик", x: "Капсула чернил: пустой браслет и реактив, больше ничего. Раздави на ходу — чернила разлетаются по рельсам, и сферы пишут кляксы. Полторы минуты тебя нет в журнале. Не трать её на одну сферу: дави, когда их много, и проходи весь коридор." },
  { t: "Мастерская: что из чего", a: "Пётр Глотов, наладчик шагоходов", x: "Из опытного сплава — заклёпки, клепальный пистолет и ленты самописцев. Из шарниров шагохода — перегрузочный излучатель, шагоходик-турель и сбруя. Из коконного шёлка — повязки, сыворотка «Выход» и плащ. Из пустых браслетов — гасители, чернила и дротики. Всё это валяется по корпусу: подбирай раньше подборщиков." },
  { t: "Сбруя и жёлоб", a: "Пётр Глотов, наладчик шагоходов", x: "Жёлоб отбраковки — короткий путь вниз, но без страховки в нём не удержаться: разгонишься и разобьёшься на повороте. Сбруя пилота шагохода годится вместо страховки: карабин на направляющую — и скользишь. Пилоты так спускались к нижним ангарам, когда клеть стояла." },
  { t: "Ставки на «Цаплю»", a: "Пилоты Шагодрома", x: "Ставки на заезд: «Проба» против «Цапли». За «Пробу» — Пётр, банка тушёнки. За «Цаплю» — все остальные, по сухарю. Судья — Зинаида. Ниже: заезд отменён, «Цапля» ушла с трассы и легла спать в ангаре. Сухари возвращены. Тушёнку Пётр съел сам, сказал — за моральный ущерб." },
  { t: "Письмо в шелковичную", a: "Пётр Глотов, наладчик шагоходов", x: "Марфуша, ты сказала, что пилоты пахнут маслом, а не цветами. Цветов в корпусе нет. Масло есть. Я принёс тебе моток лучшего шёлка из выводковой — сам снимал, весь в писке был. Не нравится масло — могу пахнуть шёлком. Или хлоркой из обмывочной. Выбирай. Я на всё согласен, кроме цветов: их нет." },
  { t: "Жалобы на Опытника", a: "Ящик для жалоб у раздаточной", x: "Жалоба первая: Опытник называет нас материалом. Ответ журнала: принято к сведению. Жалоба вторая: тасовка в ноль-ноль мешает спать. Ответ: сон — неучтённая величина. Жалоба третья: в каше камни. Ответ: камни учтены как примесь. Жалоба четвёртая, без подписи: верните имена. Ответ отсутствует. Ящик опечатан." },
  { t: "Считалка общежития", a: "Дети общежития", x: "Раз — колокол, два — поворот, три — коридор уехал вперёд. Четыре — сфера скрипит пером, пять — ты не номер, ты дом. Шесть — паёк, а семь — новичок: без браслета, без бирки, молчок. Восемь — считай, девять — считай, десять — кто пропал, тот не пропал, выходи играть." },
  { t: "О смазке", a: "Зинаида Глотова, главный конструктор шагоходов", x: "Кто опять смазывал колено «Цапли» кухонным жиром? Она теперь скрипит и пахнет котлетами, и за ней ходят гончие. Харитон, не отпирайся, я узнала твой жир по запаху. Колено промыть, жир вернуть на кухню, гончим объяснить, что «Цапля» несъедобна." },
  { t: "Объяснительная", a: "Харитон Деев, повар корпуса", x: "Жир был не кухонный, а праздничный. Колено скрипело, «Цапля» плакала — мне так показалось. Гончим объяснять не возьмусь: они не слушают поваров, они слушают котлеты. В следующий раз смажу маслом из ангара и буду пахнуть как пилот. Марфа говорит, это ужасно." },
  { t: "Стихи из Глухой комнаты", a: "Лада Ольховская, лоцман секций", x: "Мы не номера, мы — шаги в темноте: нас тасуют, а мы всё те же, всё те. Коридор уезжает, но голос — со мной: я найду тебя, слышишь, по звуку одной. Колокол бьёт — я держусь за стену, досчитаю до трёх и тебя не забуду." },
  { t: "Объявление: потерялся", a: "Тиша Зотов, двенадцать лет", x: "Потерялся шагоходик «Цыплёнок», модель для детей, пищит на каждом шаге. Ушёл после тасовки в сторону Шагодрома. Если увидите — не стреляйте, он не опасный, он торгует деталями и считает до трёх. Верните в спальню, пожалуйста. Я его учил считать." },
  { t: "Список долгов наладчика", a: "Пётр Глотов, наладчик шагоходов", x: "Должен Зинаиде: смазку для «Цапли», правильную, и извинение за жир — хотя жир был не мой. Должен Марфе: цветы, которых нет. Должен Харитону: банку тушёнки, ту самую. Должен Опытнику: ничего. Он считает, что я ему должен смену. Пусть считает, он это любит." },
  { t: "Сон про Трещину", a: "Образец номер восемьдесят", x: "Снилось, что я спускаюсь по скобам, а внизу кто-то считает: «Сорок одна… сорок две…» Дохожу до последней скобы, и голос говорит: «Эта — для того, кто спустится следом». Я хотел ответить, что я не тот. А голос сказал: «Тот, не тот — неважно. Важно, что следом». Проснулся от колокола. Записал, пока не забыл." },
  { t: "Про кашу", a: "Харитон Деев, повар корпуса", x: "Каша образца: крупа — по норме, вода — по норме, соль — по норме, а вкус — по совести. Опытник требует указывать вкус в журнале. Я пишу: «вкус — удовлетворительный». Он спрашивает, как измерен вкус. Я отвечаю: ложкой. Он записал. Теперь у нас вкус измеряется ложкой, официально." },
  { t: "Расписание вечернего выпуска", a: "Инна Ковригина, ведущая радиожурнала", x: "После отбоя — новости секций: что уехало, что приехало. Потом имена: кто прошёл стенды, кто вышел из шлюза, кто ушёл к краю. Потом музыка — то, что удалось записать: гудение коконника, колокол тасовки, кто-нибудь поёт. Последним — одно имя наугад из старых списков, чтобы помнили. Вчера было имя Лидия." },
  { t: "Модель шлюза", a: "Ефим Глотов, модельщик", x: "Верхняя полка модельной: модель шлюза, кресло, две двери. Если её уронить, кресло ломается ровно посередине. Я ронял её одиннадцать раз — Пахомову, ведущим, комиссии. Все слушали треск и говорили: «Смелее». На двенадцатый раз я поставил её на полку и больше не трогаю. Пусть стоит. Пусть падает в чьей-нибудь голове." },
  { t: "Скупщик брака о себе", a: "Скупщик брака", x: "Я сам брак. Слух ниже нормы, сказал журнал, когда мне было девять. С тех пор живу на складе. Брак не учитывают, поэтому я свободнее всех в корпусе. Торгую тем, чего нет в журнале. Однажды Опытник спросил по рупору, кто там шуршит на складе. Я ответил: никто. Он записал: «никто». Так и живу — никем, но с товаром." },
  { t: "Про собак", a: "Тиша Зотов, двенадцать лет", x: "Бурые в изоляторе не злые, они просто голодные и переделанные. Одна, с белым ухом, берёт сухарь с ладони, если не дышать. Фома говорит, у них в роду есть пёс первых, который пошёл сам. Я думаю, Белоухая тоже пошла бы сама, если бы её выпустили. Я её когда-нибудь выпущу. Только не говорите Опытнику." },
  { t: "Хозяйка поёт", a: "Марфа, шелковичница", x: "Снимаю шёлк в шелковичной и слышу, как за стеной гудит Хозяйка коконника: низко и ровно, как колыбельную. Старые шелковичницы говорят, что её звали Ульяна и что она пошла в шлюз сама. Когда я пою за работой, гудение подстраивается под меня. Мы поём вдвоём, через стену. Опытник записал: «помеха»." },
  { t: "Опыт номер ноль", a: "Заметка на полях журнала", x: "Мелко, карандашом, на полях журнала опытов: «Опыт номер ноль — не поставлен. Условие: спросить материал, чего он хочет. Причина отмены: материал отвечает непредсказуемо, ответы не сводятся в таблицу». Ниже другим почерком: «Поставьте. Мы ответим». Ещё ниже: «Отклонено. Журнал»." }
] });

